"""Offline curation compiler. Every operator has separate Python/TypeScript arithmetic.
No source text or user input is executed by generated lesson code.
"""
import math
OPS={}
def op(name,labels,out,ts,py,question,explain,kind='bars'):
 OPS[name]=dict(labels=labels.split(),out=out.split(),ts=ts,py=py,question=question,explain=explain,kind=kind)
op('lossbet','Gain Loss Lambda P','Value','[p[3]*p[0]-(1-p[3])*p[2]*p[1]]',lambda p:[p[3]*p[0]-(1-p[3])*p[2]*p[1]],'A toy bet wins {Gain} with probability {P}; otherwise it loses {Loss}. Losses count {Lambda} times gains. What is its expected model value?','The model weights a loss separately from its probability. A positive cash expectation can coexist with a negative model valuation.')
op('reference','Outcome Reference Lambda','Value','[p[0]>=p[1]?p[0]-p[1]:p[2]*(p[0]-p[1])]',lambda p:[(p[0]-p[1])*(1 if p[0]>=p[1] else p[2])],'An outcome is {Outcome}, its reference is {Reference}, and negative differences count {Lambda} times positive ones. What is its signed model value?','The same outcome changes sign when its reference crosses it. The reference is a stated assumption, not a measure of anyone’s feelings.','timeline')
op('sqrtgap','Low High Shift','Gap','[Math.sqrt(p[1]+p[2])-Math.sqrt(p[0]+p[2])]',lambda p:[math.sqrt(p[1]+p[2])-math.sqrt(p[0]+p[2])],'A toy value curve is square root of the amount. Compare amounts {Low}+{Shift} and {High}+{Shift}. What is the value gap?','The square-root curve bends. Equal cash gaps have smaller value gaps farther from zero. This is the stated curve, not a universal preference.','curve')
op('threshold','Loss Lambda Probability','Gain','[(1-p[2])*p[0]*p[1]/p[2]]',lambda p:[(1-p[2])*p[0]*p[1]/p[2]],'A toy gamble loses {Loss} otherwise and wins with probability {Probability}. Losses have weight {Lambda}. What gain makes expected model value zero?','Setting the weighted expected value to zero isolates the compensation needed for the possible loss.')
op('target','Target Hourly','Hours','[p[0]/p[1]]',lambda p:[p[0]/p[1]],'A toy worker stops exactly at income {Target} and earns {Hourly} per hour. After how many hours do they stop?','A fixed income target produces fewer hours on high-rate days. This illustrates the stopping rule; it cannot establish a real worker’s motive.','timeline')
op('net','Endowment Bonus Penalty','Net','[p[0]+p[1]-p[2]]',lambda p:[p[0]+p[1]-p[2]],'A toy account starts at {Endowment}, receives {Bonus}, and pays back {Penalty}. What final balance remains?','Track the final balance as well as the wording. Equivalent cash paths can carry different descriptions without changing the arithmetic.','timeline')
op('rates','HitA TotalA HitB TotalB','Gap','[100*(p[0]/p[1]-p[2]/p[3])]',lambda p:[100*(p[0]/p[1]-p[2]/p[3])],'A toy comparison has {HitA}/{TotalA} in A and {HitB}/{TotalB} in B. What is A minus B in percentage points?','Divide by each group’s own denominator before subtracting. A rate difference alone does not explain the cause of that difference.','grid')
op('annual','Start Rate Years','Balance','[p[0]*Math.pow(1+p[1],p[2])]',lambda p:[p[0]*(1+p[1])**p[2]],'A toy balance starts at {Start}, compounds at rate {Rate} per period, for {Years} periods. What balance results?','Compounding applies the rate to the changing balance. Compare the same horizon under the altered rate.','timeline')
op('premium','Probability Reduction Cost','Net','[p[0]*p[1]-p[2]]',lambda p:[p[0]*p[1]-p[2]],'A toy policy reduces a loss by {Reduction} with probability {Probability} and costs {Cost}. What is its expected cash gain minus cost?','Expected cash value weights the avoided loss by its probability. Utility, liquidity and risk tolerance are separate assumptions.')
op('slope','GainSlope LossSlope Size','Difference','[(p[1]-p[0])*p[2]]',lambda p:[(p[1]-p[0])*p[2]],'A toy response has slope {GainSlope} for gains and {LossSlope} for losses. For size {Size}, how much larger is the loss-side response?','Two different slopes encode asymmetric sensitivity. The chosen slopes illustrate a model and do not validate a psychological or brain finding.','curve')
op('anchor','Anchor Evidence Weight','Estimate','[p[2]*p[0]+(1-p[2])*p[1]]',lambda p:[p[2]*p[0]+(1-p[2])*p[1]],'A toy estimate gives anchor {Anchor} weight {Weight} and evidence {Evidence} the remaining weight. What estimate results?','An estimate can move because the arbitrary starting point moves. The contrast holds the evidence fixed to expose that channel.')
op('factorial','N Estimate','Fold','[Array.from({length:p[0]},(_,i)=>i+1).reduce((a,b)=>a*b,1)/p[1]]',lambda p:[math.factorial(int(p[0]))/p[1]],'An estimate for {N} factorial is {Estimate}. How many times larger is the exact product?','The complete product is invariant to order; a rushed estimate can depend on which factors are encountered first.')
op('shrink','Estimate Weight Other','Mean','[(p[0]*p[1]+p[2])/(p[1]+1)]',lambda p:[(p[0]*p[1]+p[2])/(p[1]+1)],'A toy pooled estimate gives {Estimate} weight {Weight} and another estimate {Other} weight 1. What is the weighted mean?','A pooled result depends on both estimates and their weights. A larger headline alone is not stronger evidence.','intervals')
op('adjust','Start Target Steps Fraction','Estimate','[p[1]+(p[0]-p[1])*Math.pow(1-p[3],p[2])]',lambda p:[p[1]+(p[0]-p[1])*(1-p[3])**p[2]],'Starting at {Start}, move fraction {Fraction} of the remaining distance toward {Target} for {Steps} steps. Where does the estimate finish?','Each adjustment leaves a fraction of the original distance. Stopping after a small number of steps preserves dependence on the start.','timeline')
op('replication','Positive Studies','Share','[100*p[0]/p[1]]',lambda p:[100*p[0]/p[1]],'A toy replication set has {Positive} positive results among {Studies} studies. What percentage is positive?','The observed share is a descriptive count. Designs, precision and selection still matter before generalizing from that count.','grid')
op('debt','Balance Interest Payment','Next','[p[0]*(1+p[1])-p[2]]',lambda p:[p[0]*(1+p[1])-p[2]],'A toy balance of {Balance} accrues interest {Interest}, then payment {Payment}. What balance remains?','A salient payment can be smaller than the new interest. The calculation separates the displayed payment from the balance path.','timeline')
op('tip','Bill Share TipRate','Average','[p[0]*p[1]*p[2]]',lambda p:[p[0]*p[1]*p[2]],'In a toy sample the bill is {Bill}; fraction {Share} tip at rate {TipRate}, the rest tip zero. What is the average tip?','The conditional tip and the share who tip jointly determine the average. A higher selected rate need not lift the overall mean.')
op('survival','Total Saved','Lost','[p[0]-p[1]]',lambda p:[p[0]-p[1]],'Of {Total} toy cases, {Saved} are saved. How many are lost under the same outcome?','Saved and lost use the same denominator and add to the stated total. Wording cannot change that accounting.','grid')
op('relative','Saving Price','Percent','[100*p[0]/p[1]]',lambda p:[100*p[0]/p[1]],'A toy saving is {Saving} on a price of {Price}. What percentage of the original price is saved?','The cash saving is the numerator; the reference price supplies the denominator. The same saving can therefore have different relative sizes.')
op('fee','Base Discount Surcharge','Final','[p[0]-p[1]+p[2]]',lambda p:[p[0]-p[1]+p[2]],'A toy price starts at {Base}, subtracts discount {Discount}, and adds surcharge {Surcharge}. What is the final price?','Compare final prices under the two labels. Fairness or preference judgments are not implied by equal arithmetic.')
op('annuity','Payment Periods Rate','Present','[p[2]===0?p[0]*p[1]:p[0]*(1-Math.pow(1+p[2],-p[1]))/p[2]]',lambda p:[p[0]*p[1] if p[2]==0 else p[0]*(1-(1+p[2])**-p[1])/p[2]],'A toy annuity pays {Payment} at each period end for {Periods} periods; discount rate {Rate}. What is its present value?','A stream of payments and its discounted lump sum are two representations of the same stated cash flow.','timeline')
op('bayes','Prior Sensitivity FalsePositive','Posterior','[p[0]*p[1]/(p[0]*p[1]+(1-p[0])*p[2])]',lambda p:[p[0]*p[1]/(p[0]*p[1]+(1-p[0])*p[2])],'A toy condition has prevalence {Prior}; a test catches fraction {Sensitivity} of cases and flags fraction {FalsePositive} of noncases. Given a positive, what probability is a case?','Count true and false positives in one common population. A test’s sensitivity is not the probability of a condition after a positive.','grid')
op('inertia','Default Other Inertia','Final','[p[2]*p[0]+(1-p[2])*p[1]]',lambda p:[p[2]*p[0]+(1-p[2])*p[1]],'A toy population keeps default contribution {Default} with probability {Inertia}; otherwise chooses {Other}. What is the mean contribution?','The aggregate combines retained defaults and active choices. Automatic participation and the chosen contribution rate are different outcomes.')
op('effect','MeanA MeanB SD','D','[(p[0]-p[1])/p[2]]',lambda p:[(p[0]-p[1])/p[2]],'Two toy means are {MeanA} and {MeanB}, with common standard deviation {SD}. What is their standardized difference?','A standardized effect divides the raw difference by spread. It does not by itself describe practical importance or replication success.','intervals')
op('cost','Annual Years SwitchCost','Saving','[p[0]*p[1]-p[2]]',lambda p:[p[0]*p[1]-p[2]],'A toy switch saves {Annual} per year for {Years} years and costs {SwitchCost} now. Ignoring discounting, what is its net saving?','Include the switching cost and horizon. Inertia may have a financial cost, but this model alone cannot explain real choices.')
op('beta','Soon Later Delay Beta Delta','Advantage','[p[3]*Math.pow(p[4],p[2])*p[1]-p[0]]',lambda p:[p[3]*p[4]**p[2]*p[1]-p[0]],'A toy model values immediate {Soon} normally, but delayed {Later} after {Delay} periods as Beta {Beta} times Delta {Delta} to the delay. What is delayed minus immediate value?','An extra present-time weight can reverse the ranking when an option becomes immediate. The weights are explicit model assumptions.','timeline')
op('hyperbolic','Amount K Delay','Value','[p[0]/(1+p[1]*p[2])]',lambda p:[p[0]/(1+p[1]*p[2])],'A toy delayed amount {Amount} is discounted by dividing by 1 + {K} × delay {Delay}. What is its value now?','The same added delay has a larger proportional effect near the present under this hyperbolic rule.','curve')
op('uptake','Eligible Uptake Increase','Added','[p[0]*p[1]*p[2]]',lambda p:[p[0]*p[1]*p[2]],'A toy program has {Eligible} eligible units, uptake fraction {Uptake}, and added amount {Increase} per participant. What total is added?','Separate the effect among participants from the share who participate. Scaling a program requires both pieces.')
op('commit','Income Fraction Return Periods','Balance','[p[0]*p[1]*(p[2]===0?p[3]:(Math.pow(1+p[2],p[3])-1)/p[2])]',lambda p:[p[0]*p[1]*(p[3] if p[2]==0 else ((1+p[2])**p[3]-1)/p[2])],'A toy saver deposits Income {Income} × Fraction {Fraction} each period end for {Periods} periods; return {Return}. What balance accumulates?','A commitment changes the deposit rule. The accumulated balance follows the stated cash flows; uptake and real behavior require separate evidence.','timeline')
op('sunk','FutureBenefit FutureCost PastCost','Net','[p[0]-p[1]]',lambda p:[p[0]-p[1]],'A toy decision has future benefit {FutureBenefit}, future cost {FutureCost}, and an unrecoverable past cost {PastCost}. What is the future net benefit?','The sunk payment is absent from the future comparison because either choice leaves it paid. A past bill cannot change the remaining payoff.')
op('accounts','Total Locked Need','Shortfall','[Math.max(0,p[2]-(p[0]-p[1]))]',lambda p:[max(0,p[2]-(p[0]-p[1]))],'A toy household has {Total}, ring-fences {Locked}, and must pay {Need} from the remainder. What is the shortfall?','The label changes which funds are treated as available. It does not change the household’s total resources.','grid')
op('breakeven','Loss Win Probability','Expected','[p[2]*p[1]-(1-p[2])*p[0]]',lambda p:[p[2]*p[1]-(1-p[2])*p[0]],'A toy gamble gains {Win} with probability {Probability} and loses {Loss} otherwise. What is its expected cash change?','Reaching an emotionally important balance is different from maximizing expected cash change. Neither guarantees the outcome of one play.')
op('flow','Income Days Spend','Remaining','[p[0]-p[1]*p[2]]',lambda p:[p[0]-p[1]*p[2]],'A toy budget starts with {Income} and spends {Spend} per day for {Days} days. What remains?','The timing of an inflow and the rate of spending determine the remaining buffer. The schedule is an illustration, not observed household data.','timeline')
op('groupvalue','First Second Lambda','Separate','[Math.sqrt(Math.abs(p[0]))*(p[0]>=0?1:-p[2])+Math.sqrt(Math.abs(p[1]))*(p[1]>=0?1:-p[2])]',lambda p:[math.sqrt(abs(p[0]))*(1 if p[0]>=0 else -p[2])+math.sqrt(abs(p[1]))*(1 if p[1]>=0 else -p[2])],'Two toy changes {First} and {Second} are valued separately by signed square root, with loss weight {Lambda}. What is their combined model value?','Combining outcomes before valuation and valuing them separately need not agree under a curved value function.','curve')
op('ratio','Sell Buy','Ratio','[p[0]/p[1]]',lambda p:[p[0]/p[1]],'A toy seller asks {Sell}; a buyer offers {Buy} for the same item. What is the sell-to-buy ratio?','The ratio describes a valuation gap. It does not identify whether ownership, procedures or information caused it.')
op('trade','Before SwitchFee After','Gain','[p[2]-p[0]-p[1]]',lambda p:[p[2]-p[0]-p[1]],'Keeping a toy option yields {Before}. Switching yields {After} and costs {SwitchFee}. What is the gain from switching?','Make the opportunity cost visible before judging a refusal to switch. Equal-risk labels can obscure a straightforward payoff difference.')
op('risk','Cases ActionRisk InactionRisk','Difference','[p[0]*(p[2]-p[1])]',lambda p:[p[0]*(p[2]-p[1])],'Across {Cases} toy cases, action risk is {ActionRisk} and inaction risk {InactionRisk}. How many fewer expected harms come with action?','Count both action and inaction using the same population. These are specified risks in a toy comparison.')
op('funnel','Visitors Stop Buy','Purchases','[p[0]*p[1]*p[2]]',lambda p:[p[0]*p[1]*p[2]],'Of {Visitors} toy visitors, fraction {Stop} stop and fraction {Buy} of those buy. How many purchases are expected?','More attention at the top of a funnel need not mean more final choices. Conditional conversion and reach jointly determine the result.','grid')
op('diversify','Stocks Bonds Budget','StockMoney','[p[2]*p[0]/(p[0]+p[1])]',lambda p:[p[2]*p[0]/(p[0]+p[1])],'A toy investor splits {Budget} equally across {Stocks} stock funds and {Bonds} bond funds. How much goes to stocks?','Equal allocation over menu items is not equal allocation over asset classes. The menu changes the resulting exposure.','grid')
op('search','Options Attributes Seconds','Checks','[p[0]*p[1]*p[2]]',lambda p:[p[0]*p[1]*p[2]],'A toy decision inspects {Attributes} attributes for each of {Options} options, spending {Seconds} seconds per check. What total time is needed?','Decision cost depends on both the number of options and the dimensions compared. A smaller interface can change this cost without removing alternatives.','timeline')
op('dominance','CostA BenefitA CostB BenefitB','NetGap','[(p[1]-p[0])-(p[3]-p[2])]',lambda p:[(p[1]-p[0])-(p[3]-p[2])],'Toy option A costs {CostA} and provides value {BenefitA}; B costs {CostB} and provides {BenefitB}. What is A net value minus B net value?','A dominated option and a genuine tradeoff differ. The stated value scale is necessary for this particular net comparison.','scatter')
op('ultimatum','Pie Offer Accept','Expected','[(p[0]-p[1])*p[2]]',lambda p:[(p[0]-p[1])*p[2]],'A toy proposer divides pie {Pie}, offers {Offer}, and is accepted with probability {Accept}; rejection pays zero. What is the proposer’s expected payoff?','The offered share and acceptance probability must be considered together. The assumed response is not a claim about all recipients.')
op('dictator','Pie Gift ExitCost','Kept','[p[0]-p[1]-p[2]]',lambda p:[p[0]-p[1]-p[2]],'A toy allocator starts with {Pie}, gives {Gift}, and pays fee {ExitCost}. What remains?','An allocation rule determines the available payoff. Preferences, observability and social pressure require evidence beyond the accounting.')
op('inequity','Own Other Envy','Utility','[p[0]-p[2]*Math.max(p[1]-p[0],0)]',lambda p:[p[0]-p[2]*max(p[1]-p[0],0)],'A toy utility equals own payoff {Own} minus weight {Envy} times any shortfall below other payoff {Other}. What is utility?','Payoff and model utility are separate quantities. Changing the inequality penalty can change a ranking without changing the money.')
op('trust','Endowment Sent Multiplier Returned','Sender','[p[0]-p[1]+p[1]*p[2]*p[3]]',lambda p:[p[0]-p[1]+p[1]*p[2]*p[3]],'A toy sender has {Endowment}, sends {Sent}, which is multiplied by {Multiplier}; the recipient returns fraction {Returned} of that pot. What does the sender finish with?','Sending and returning are two decisions. A multiplier creates surplus, but the sender’s payoff also depends on the return rule.','timeline')
op('public','People Endowment Contribution Multiplier','Payoff','[p[1]-p[2]+p[0]*p[2]*p[3]/p[0]]',lambda p:[p[1]-p[2]+p[2]*p[3]],'In a toy group of {People}, everyone starts with {Endowment}, contributes {Contribution}, and the pot is multiplied by {Multiplier} then split equally. What is each payoff?','Group benefit and the private return to one extra contribution differ. This symmetric case shows the accounting, not a predicted participation rate.','grid')
op('punish','Gain Fine Catch','Net','[p[0]-p[1]*p[2]]',lambda p:[p[0]-p[1]*p[2]],'A toy action earns {Gain} but incurs fine {Fine} with probability {Catch}. What is its expected cash gain?','A sanction changes the expected payoff through both its size and its probability. A payoff change does not establish how people respond.')
op('repeat','Cooperate Defect Delta','Advantage','[p[0]/(1-p[2])-p[1]]',lambda p:[p[0]/(1-p[2])-p[1]],'Toy cooperation pays {Cooperate} forever, discounted by {Delta} each round. Defection pays {Defect} once, then zero. What is cooperation’s discounted advantage?','Continuation can make a one-time temptation unattractive. The comparison depends on the specified future and discount factor.','timeline')
op('growth','Baseline Percent','Final','[p[0]*(1+p[1]/100)]',lambda p:[p[0]*(1+p[1]/100)],'A toy baseline is {Baseline}; it changes by {Percent} percent. What is the final level?','A relative percentage uses the baseline as denominator. It is different from the same number of percentage points.')
op('calibration','Claimed Hits Trials','Gap','[p[0]-p[1]/p[2]]',lambda p:[p[0]-p[1]/p[2]],'A toy forecast claims probability {Claimed}; {Hits} of {Trials} matched it. What is claimed probability minus observed share?','Calibration compares forecasts with repeated outcomes. One correct or incorrect outcome cannot settle a probability claim.','grid')
op('rank','People Above','Minimum','[Math.max(0,p[1]-Math.floor(p[0]/2))]',lambda p:[max(0,p[1]-math.floor(p[0]/2))],'In a toy group of {People}, {Above} claim to be strictly above the group median. At least how many claims cannot all be right?','At most half the group can be strictly above its median. This logical ceiling does not diagnose which individual is mistaken.')
op('coverage','Nominal Hits Trials','Misses','[p[2]-p[1]]',lambda p:[p[2]-p[1]],'A toy interval procedure claims coverage {Nominal}; it covers {Hits} of {Trials} targets. How many targets were missed?','Count realized coverage before trusting the stated confidence. A narrow interval can be precise in appearance and poorly calibrated.','intervals')
op('overrun','Planned Actual','Overrun','[100*(p[1]/p[0]-1)]',lambda p:[100*(p[1]/p[0]-1)],'A toy task was planned at {Planned} and used {Actual}. What percentage over the plan did it run?','The plan is the denominator for an overrun. Forecast error and its cause remain separate questions.')
op('update','Prior News Weight','Posterior','[p[0]+p[2]*(p[1]-p[0])]',lambda p:[p[0]+p[2]*(p[1]-p[0])],'A toy belief starts at {Prior}, receives estimate {News}, and moves fraction {Weight} toward it. What belief results?','Different update weights can create asymmetric learning from equally informative news. The toy rule is an assumption, not a psychological measurement.')
op('conjunction','First Conditional','Joint','[p[0]*p[1]]',lambda p:[p[0]*p[1]],'A toy event has probability {First}; conditional on it, an additional property occurs with probability {Conditional}. What is the joint probability?','The conjunction occupies only part of the original event. Adding a condition cannot make the same event more probable.','grid')
op('mixture','Weight RateA RateB','Rate','[p[0]*p[1]+(1-p[0])*p[2]]',lambda p:[p[0]*p[1]+(1-p[0])*p[2]],'A toy mixture puts fraction {Weight} at rate {RateA} and the remainder at rate {RateB}. What is its aggregate rate?','An aggregate mixes groups with their weights. Changes in composition can move it while component rates stay fixed.')
op('accuracy','Correct Total','Accuracy','[p[0]/p[1]]',lambda p:[p[0]/p[1]],'A toy assessment has {Correct} correct answers among {Total}. What fraction is correct?','A score needs its denominator. This descriptive fraction does not establish skill, causation or the accuracy of another population.','grid')
op('percentile','Actual Guessed','Error','[p[1]-p[0]]',lambda p:[p[1]-p[0]],'A toy result is at percentile {Actual}; the forecast was percentile {Guessed}. What signed forecasting error is guessed minus actual?','A rank gap describes the two numbers. Measurement noise and mathematical coupling can also affect patterns in such gaps.','scatter')
op('groupedloss','Gain Loss Lambda Group','Value Cash','[p[3]===1?2*p[0]-p[2]*p[1]:(2*p[0]-p[1]>=0?2*p[0]-p[1]:p[2]*(2*p[0]-p[1])),2*p[0]-p[1]]',lambda p:[2*p[0]-p[2]*p[1] if p[3]==1 else (2*p[0]-p[1])*(1 if 2*p[0]-p[1]>=0 else p[2]),2*p[0]-p[1]],'A fixed toy cash path is gain {Gain}, loss {Loss}, gain {Gain}. Negative values have weight {Lambda}. Group {Group} means separate if 1, combined if 3. What model value results?','The cash path stays fixed. Valuing each interval before adding can disagree with adding the cash first under an asymmetric value rule.','timeline')
op('frame','Total Saved Frame','Display Saved Lost','[p[2]===0?p[1]:p[0]-p[1],p[1],p[0]-p[1]]',lambda p:[p[1] if p[2]==0 else p[0]-p[1],p[1],p[0]-p[1]],'In a toy population of {Total}, {Saved} are saved. Frame {Frame} displays saved when 0 and lost when 1. Which count does that frame display?','The displayed count changes its meaning with the frame; the saved and lost counts describe one unchanged outcome.','grid')
op('abovemean','Others Value Outlier','Above Mean','[(p[1]>(p[0]*p[1]+p[2])/(p[0]+1)?p[0]:0)+(p[2]>(p[0]*p[1]+p[2])/(p[0]+1)?1:0),(p[0]*p[1]+p[2])/(p[0]+1)]',lambda p:[(p[0] if p[1]>(p[0]*p[1]+p[2])/(p[0]+1) else 0)+(1 if p[2]>(p[0]*p[1]+p[2])/(p[0]+1) else 0),(p[0]*p[1]+p[2])/(p[0]+1)],'A toy group has {Others} people scoring {Value} each and one scoring {Outlier}. How many are strictly above the group mean?','A mean is not a median. Many people can be above a mean when a low outlier pulls it down; the median ceiling cannot simply be substituted.','grid')
# Counts and point estimates are not fabricated confidence intervals.
for _name in ['shrink','effect','coverage']:
 OPS[_name]['kind']='grid' if _name!='effect' else 'bars'
